import{GlpiFormDestinationAutoConfigController}from"/js/modules/Forms/DestinationAutoConfigController.js";import{GlpiFormDestinationConditionController}from"/js/modules/Forms/DestinationConditionController.js";export class GlpiFormDestinationAccordionController{constructor(){this.#o()}triggerWatchers(){new GlpiFormDestinationAutoConfigController;new GlpiFormDestinationConditionController}#o(){const o=document.querySelector("#glpi-destinations-accordion");o.addEventListener("show.bs.collapse",async o=>{const t=o.target;const r=t.querySelector(".accordion-body");if(r.innerHTML.trim()!==""){return}r.innerHTML='<div class="text-center"><div class="spinner-border text-primary mb-3" role="status"></div></div>';const n=await $.ajax({url:`${CFG_GLPI.root_doc}/Form/${t.dataset.form}/Destinations/${t.dataset.formDestination}`,method:"GET"});$(r).html(n);this.triggerWatchers()});o.classList.remove("pe-none")}}